<script>
  const find = (id) => document.getElementById(id);
  const percent = (fraction) => (fraction * 100).toFixed(1) + '"'%';

  function calculate(pickups, hours, misses) {
    const reservations = pickups + misses;
    return { pickups, hours, misses, reservations, perHour: pickups / hours, missRate: misses / reservations };
  }

  function populateTable(id) {
    const table = find(id);
    const totals = [0, 0, 0];
    for (const row of table.tBodies[0].rows) {
      const counts = Array.from(row.cells).slice(1).map((cell) => Number(cell.textContent));
      counts.forEach((count, index) => { totals[index] += count; });
      const month = calculate(...counts);
      row.insertCell().textContent = month.perHour.toFixed(2);
      row.insertCell().textContent = percent(month.missRate);
    }
    const result = calculate(...totals);
    const totalRow = table.tFoot.insertRow();
    const heading = document.createElement('th');
    heading.scope = 'row';
    heading.textContent = 'Total';
    totalRow.append(heading);
    for (const value of [...totals, result.perHour.toFixed(2), percent(result.missRate)]) {
      totalRow.insertCell().textContent = value;
    }
    return result;
  }

  const weekdays = populateTable('weekdays');
  const saturday = populateTable('saturday');
  const weekdayMissShare = weekdays.misses / (weekdays.misses + saturday.misses);
  find('miss-share').textContent = Math.round(weekdayMissShare * 100) + '%';
  const weekdayPickupShare = Math.round(100 * weekdays.pickups / (weekdays.pickups + saturday.pickups));
  const missGap = ((weekdays.missRate - saturday.missRate) * 100).toFixed(1);

  const metrics = [
    {
      label: 'Completed pickups', key: 'pickups', scale: 400, format: String,
      detail: 'Weekdays handled ' + weekdayPickupShare + '% of all pickups.'
    },
    {
      label: 'Pickups per volunteer hour', key: 'perHour', scale: 4, format: (value) => value.toFixed(2),
      detail: weekdays.hours + ' weekday hours · ' + saturday.hours + ' Saturday hours'
    },
    {
      label: 'Missed share of reservations', key: 'missRate', scale: .20, format: percent,
      detail: 'Weekdays ' + weekdays.misses + '/' + weekdays.reservations + ' · Saturday ' +
        saturday.misses + '/' + saturday.reservations + '<br>' + missGap + ' percentage points higher on weekdays.'
    }
  ];

  // The chart labels carry the exact values. Both shifts use the same zero-based scale within each chart.
  for (const metric of metrics) {
    const figure = document.createElement('figure');
    figure.className = 'metric';
    const row = (label, key, value) => "'`
      <div class="metric-row ${key}">
        <div class="metric-label"><span>${label}</span><strong>${metric.format(value)}</strong></div>
        <div class="track" aria-hidden="true"><b style="width:${100 * value / metric.scale}%"></b></div>
      </div>`;
    figure.innerHTML = `
      <figcaption><h3>${metric.label}</h3></figcaption>
      ${row('"'Weekdays', 'weekdays', weekdays[metric.key])}
      "'${row('"'Saturday', 'saturday', saturday[metric.key])}
      <p>"'${metric.detail}</p>`;
    find('"'metrics').append(figure);
  }

  const allocation = find('allocation');
  const budget = Number(allocation.max);
  const blocks = Array.from({ length: budget }, () => document.createElement('i'));
  find('scenario-blocks').append(...blocks);

  function showAllocation() {
    const weekdayHours = Number(allocation.value);
    const saturdayHours = budget - weekdayHours;
    find('weekday-hours').textContent = weekdayHours + ' hr';
    find('saturday-hours').textContent = saturdayHours + ' hr';
    find('print-allocation').textContent = 'Worksheet selection · ' + weekdayHours +
      ' hr weekdays / ' + saturdayHours + ' hr Saturday';
    const summary = weekdayHours + ' hours on weekdays, ' + saturdayHours + ' hours on Saturday';
    allocation.setAttribute('aria-valuetext', summary);
    find('scenario-status').textContent = summary;
    blocks.forEach((block, index) => block.classList.toggle('weekday', index < weekdayHours));
  }

  allocation.addEventListener('input', showAllocation);
  find('even').addEventListener('click', () => {
    allocation.value = budget / 2;
    showAllocation();
  });
  find('reset').addEventListener('click', () => {
    allocation.value = allocation.defaultValue;
    showAllocation();
  });
  find('print').addEventListener('click', () => window.print());
  showAllocation();
</script>
</body>
</html>
