const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const { pathToFileURL } = require('node:url');
const os = require('node:os');
const path = require('node:path');
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'pantry-test-'));
const chrome = spawn(process.argv[2], [
  '--single-process', '--no-zygote', '--no-sandbox', '--disable-gpu',
  '--disable-background-networking', '--no-first-run', '--user-data-dir=' + profile,
  '--remote-debugging-pipe', 'about:blank'
], { stdio: ['ignore', 'ignore', 'ignore', 'pipe', 'pipe'] });
const pending = new Map();
let counter = 0;
let incoming = '';
chrome.stdio[4].setEncoding('utf8').on('data', (chunk) => {
  incoming += chunk;
  let delimiter;
  while ((delimiter = incoming.indexOf('\\0')) >= 0) {
    const response = JSON.parse(incoming.slice(0, delimiter));
    incoming = incoming.slice(delimiter + 1);
    const callbacks = pending.get(response.id);
    if (callbacks) {
      pending.delete(response.id);
      if (response.error) callbacks.reject(response.error);
      else callbacks.resolve(response.result);
    }
  }
});
function command(method, params = {}, sessionId) {
  const id = ++counter;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    chrome.stdio[3].write(JSON.stringify({ id, method, params, sessionId }) + '\\0');
  });
}
(async () => {
  const timeout = setTimeout(() => { chrome.kill(); throw new Error('Browser check timed out'); }, 10000);
  try {
    const { targetInfos } = await command('Target.getTargets');
    const { sessionId } = await command('Target.attachToTarget', {
      targetId: targetInfos.find((target) => target.type === 'page').targetId, flatten: true
    });
    const page = (method, params) => command(method, params, sessionId);
    const evaluate = async (expression) => {
      const reply = await page('Runtime.evaluate', { expression, returnByValue: true });
      if (reply.exceptionDetails) throw new Error(reply.exceptionDetails.exception.description);
      return reply.result.value;
    };
    await page('Page.navigate', { url: pathToFileURL(path.resolve('pantry-worksheet.html')).href });
    for (let attempt = 0; attempt < 30; attempt++) {
      if (await evaluate('"'!!document.querySelector("#scenario-blocks i")'"')) break;
      await new Promise((resolve) => setTimeout(resolve, 50));
    }
    const expected = {
      weekdays: [
        ['Jan',82,24,14], ['Feb',91,24,16], ['Mar',88,26,19], ['Apr',96,26,17], ['Total',357,100,66],
      ],
      saturday: [
        ['Jan',54,16,8], ['Feb',63,18,7], ['Mar',71,18,6], ['Apr',74,20,6], ['Total',262,72,27],
      ]
    };
    for (const [id, rows] of Object.entries(expected)) {
      const actual = await evaluate("'`Array.from(document.querySelectorAll('"'#"'${id} tbody tr, #${id} tfoot tr'"'),
        (row) => Array.from(row.cells, (cell) => cell.textContent))"'`);
      assert.deepEqual(actual, rows.map(([month, pickups, hours, misses]) =>
        [month, String(pickups), String(hours), String(misses), (pickups/hours).toFixed(2),
          (misses*100/(pickups+misses)).toFixed(1) + '"'%']));
    }
    assert.deepEqual(await evaluate('Array.from(document.querySelectorAll(\".metric strong\"), el => el.textContent)'),
      ['357', '262', '3.57', '3.64', '15.6%', '9.3%']);
    const getSplit = () => evaluate("'`[
      document.getElementById('"'weekday-hours').textContent,
      document.getElementById('saturday-hours').textContent,
      document.querySelectorAll('#scenario-blocks .weekday').length,
      document.querySelectorAll('#scenario-blocks i').length
    ]"'`);
    const assertSplit = async (hours) => assert.deepEqual(await getSplit(),
      [hours + '"' hr', (12-hours) + ' hr', hours, 12]);
    await assertSplit(8);
    await evaluate('document.getElementById(\"even\").click()');
    await assertSplit(6);
    await evaluate('document.getElementById(\"reset\").click()');
    await assertSplit(8);
    await evaluate('document.getElementById(\"allocation\").focus()');
    for (const [key, code, hours] of [['ArrowRight', 39, 9], ['Home', 36, 0], ['End', 35, 12]]) {
      await page('Input.dispatchKeyEvent', { type: 'keyDown', key, windowsVirtualKeyCode: code });
      await page('Input.dispatchKeyEvent', { type: 'keyUp', key, windowsVirtualKeyCode: code });
      await assertSplit(hours);
    }
    assert.equal(await evaluate("'`window.print = () => window.printPressed = true;
      document.getElementById('"'print').click(); window.printPressed"'`), true);
    assert.match(await evaluate('"'document.getElementById(\"print-allocation\").textContent'), /12 hr weekdays \\/ 0 hr Saturday/);
    await page('Emulation.setEmulatedMedia', { media: 'print' });
    assert.equal(await evaluate('getComputedStyle(document.getElementById(\"allocation\")).display'), 'block');
    assert.equal(await evaluate('document.getElementById(\"allocation\").getClientRects().length'), 0);
    assert.equal(await evaluate('document.getElementById(\"print-allocation\").getClientRects().length'), 1);
    await page('Emulation.setEmulatedMedia', { media: 'screen' });
    for (const [width, height] of [[1280, 900], [390, 844], [375, 667], [320, 675], [844, 390]]) {
      await page('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false });
      assert.equal(await evaluate('document.documentElement.scrollWidth'), width);
      assert.equal(await evaluate("'`Array.from(document.querySelectorAll('"'button')).every(
        (button) => button.getBoundingClientRect().height >= 44)"'`), true);
    }
    await page('"'Emulation.setDeviceMetricsOverride', { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false });
    await evaluate('document.getElementById(\"reset\").click(); window.scrollTo(0, 0)');
